func TestCachedPublicKeyFinder_BasicCaching(t *testing.T) {
	// Create a temporary directory for cache
	tempDir := t.TempDir()

	// Track how many times the server is hit
	hitCount := 0
	keyID := "test-key-1"

	// Create a mock OIDC server
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		hitCount++
		if r.URL.Path == "/.well-known/openid-configuration" {
			w.Header().Set("Content-Type", "application/json")
			w.Write(mockWellKnown(r.Host, fmt.Sprintf("http://%s/jwks", r.Host)))
		} else if r.URL.Path == "/jwks" {
			w.Header().Set("Content-Type", "application/json")
			w.Write(mockJWKS(keyID))
		}
	}))
	defer server.Close()

	config := CacheConfig{
		CacheDir:          tempDir,
		MaxCacheAge:       5 * time.Minute,
		MaxCacheRetention: 1 * time.Hour,
		RefreshJitter:     0, // Disable jitter for testing
		EternalJWKSDir:    filepath.Join(tempDir, "eternal"),
		Enabled:           true,
		HTTPClient:        server.Client(),
	}

	cachedFinder := NewCachedPublicKeyFinder(config)
	ctx := context.Background()

	// First call should hit the server
	_, err := cachedFinder.getJwksWithCache(ctx, server.URL)
	require.NoError(t, err)
	require.Equal(t, 2, hitCount) // well-known + jwks

	// Second call should use cache
	initialHitCount := hitCount
	_, err = cachedFinder.getJwksWithCache(ctx, server.URL)
	require.NoError(t, err)
	require.Equal(t, initialHitCount, hitCount) // No new hits
}

func TestCachedPublicKeyFinder_CacheExpiry(t *testing.T) {
	tempDir := t.TempDir()

	hitCount := 0
	keyID := "test-key-1"

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
