func TestCachedPublicKeyFinder_FallbackToStaleCache(t *testing.T) {
	tempDir := t.TempDir()

	keyID := "test-key-1"
	serverUp := true

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !serverUp {
			http.Error(w, "Server down", http.StatusServiceUnavailable)
			return
		}
		if r.URL.Path == "/.well-known/openid-configuration" {
			w.Header().Set("Content-Type", "application/json")
			w.Write(mockWellKnown(r.Host, fmt.Sprintf("http://%s/jwks", r.Host)))
		} else if r.URL.Path == "/jwks" {
			w.Header().Set("Content-Type", "application/json")
			w.Write(mockJWKS(keyID))
		}
	}))
	defer server.Close()

	config := CacheConfig{
		CacheDir:          tempDir,
		MaxCacheAge:       100 * time.Millisecond,
		MaxCacheRetention: 1 * time.Hour,
		RefreshJitter:     0,
		Enabled:           true,
		HTTPClient:        server.Client(),
	}

	cachedFinder := NewCachedPublicKeyFinder(config)
	ctx := context.Background()

	// First call - populate cache
	_, err := cachedFinder.getJwksWithCache(ctx, server.URL)
	require.NoError(t, err)

	// Wait for cache to expire
	time.Sleep(150 * time.Millisecond)

	// Take server down
	serverUp = false

	// Should fall back to stale cache
	jwks, err := cachedFinder.getJwksWithCache(ctx, server.URL)
	require.NoError(t, err)
	require.NotNil(t, jwks)
}

func TestCachedPublicKeyFinder_EternalJWKS(t *testing.T) {
	tempDir := t.TempDir()
	eternalDir := filepath.Join(tempDir, "eternal")
	require.NoError(t, os.MkdirAll(eternalDir, 0755))

	issuer := "https://example.com"
	keyID := "eternal-key-1"

	// Write an eternal JWKS file
	sanitizedIssuer := sanitizeIssuerForPath(issuer)
	eternalPath := filepath.Join(eternalDir, sanitizedIssuer+".json")
	require.NoError(t, os.WriteFile(eternalPath, mockJWKS(keyID), 0644))

	// Create a server that's always down
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Error(w, "Server down", http.StatusServiceUnavailable)
	}))
	defer server.Close()

	config := CacheConfig{
		CacheDir:          tempDir,
		MaxCacheAge:       5 * time.Minute,
		MaxCacheRetention: 1 * time.Hour,
		RefreshJitter:     0,
		EternalJWKSDir:    eternalDir,
		Enabled:           true,
		HTTPClient:        server.Client(),
	}

	cachedFinder := NewCachedPublicKeyFinder(config)
	ctx := context.Background()

	// Should use eternal JWKS when server is down and no cache exists
	jwks, err := cachedFinder.getJwksWithCache(ctx, issuer)
	require.NoError(t, err)
	require.NotNil(t, jwks)

	// Verify it's the eternal JWKS
	var parsed map[string]interface{}
	require.NoError(t, json.Unmarshal(jwks, &parsed))
	keys := parsed["keys"].([]interface{})
	firstKey := keys[0].(map[string]interface{})
	require.Equal(t, keyID, firstKey["kid"])
}

