func TestCachedPublicKeyFinder_CleanupOldEntries(t *testing.T) {
	tempDir := t.TempDir()

	keyID := "test-key-1"

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/.well-known/openid-configuration" {
			w.Header().Set("Content-Type", "application/json")
			w.Write(mockWellKnown(r.Host, fmt.Sprintf("http://%s/jwks", r.Host)))
		} else if r.URL.Path == "/jwks" {
			w.Header().Set("Content-Type", "application/json")
			w.Write(mockJWKS(keyID))
		}
	}))
	defer server.Close()

	config := CacheConfig{
		CacheDir:          tempDir,
		MaxCacheAge:       1 * time.Millisecond,
		MaxCacheRetention: 50 * time.Millisecond,
		RefreshJitter:     0,
		Enabled:           true,
		HTTPClient:        server.Client(),
	}

	cachedFinder := NewCachedPublicKeyFinder(config)
	ctx := context.Background()

	// Create some cache entries
	for i := 0; i < 3; i++ {
		_, err := cachedFinder.getJwksWithCache(ctx, server.URL)
		require.NoError(t, err)
		time.Sleep(10 * time.Millisecond)
	}

	// Wait for entries to become old enough to clean
	time.Sleep(100 * time.Millisecond)

	// Trigger cleanup
	err := cachedFinder.CleanupAllOldEntries()
	require.NoError(t, err)

	// Verify old entries were cleaned up
	issuerDir := cachedFinder.issuerCacheDir(server.URL)
	doneDir := filepath.Join(issuerDir, "done")
	entries, err := os.ReadDir(doneDir)
	if err == nil {
		// All entries should be cleaned up
		require.Empty(t, entries)
	}
}

